import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Strategy C — Runtime Module Loading as Handler-Interpreted Ops","description":"","frontmatter":{"title":"Strategy C — Runtime Module Loading as Handler-Interpreted Ops","type":"adr","date":"2026-10-16T00:00:00.000Z","status":"proposed","status_note":"Accepted — runtime module loading is the handler, not a strategy."},"headers":[],"relativePath":"handl/project/adrs/0009-strategy-c-runtime-module-loading.md","filePath":"vendored/handl/project/adrs/0009-strategy-c-runtime-module-loading.md"}`),a={name:`handl/project/adrs/0009-strategy-c-runtime-module-loading.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0009-strategy-c-—-runtime-module-loading-as-handler-interpreted-ops" tabindex="-1">ADR-0009: Strategy C — Runtime Module Loading as Handler-Interpreted Ops <a class="header-anchor" href="#adr-0009-strategy-c-—-runtime-module-loading-as-handler-interpreted-ops" aria-label="Permalink to “ADR-0009: Strategy C — Runtime Module Loading as Handler-Interpreted Ops”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Strategy C is not a separate strategy.</strong> <code>module_ref</code> and <code>project</code> are <code>arr</code> ops already emitted by <code>rewrite_imports</code>; a handler with clauses for them interprets the graph directly. No new <code>Scheme</code> variants.</li><li><strong>The handler&#39;s operation table is the opt-in.</strong> A handler without the clauses requires the graph to be normalised (Strategy A/B) or refuses with <code>unknown op</code>; there is no directive and no capability flag.</li><li><strong>Governance is handler configuration</strong>: path allowlist, load-depth limit, resolvers (file-only by default; network only if configured), and runtime cycle detection on the load stack.</li><li><strong>Two static passes work without executing</strong>: cycle detection over the import graph, and contract inference over <code>module_ref</code>/<code>project</code> (permissive contracts, tightening via the loader&#39;s contract cache).</li><li><strong>Graduate to real <code>Scheme</code> variants only</strong> when a second handler needs them and stringly matching causes real problems; until then the closed six-combinator kernel holds.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Runtime loading looked like a third strategy, so it grew a directive, a capability flag and a separate code path. The ops already exist; a handler either interprets them or refuses, which is the same opt-in model as every other operation.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>A <code>-- @strategy runtime</code> directive</strong> — the handler&#39;s table is the switch.</li><li><strong>A <code>supports_runtime_loading</code> flag</strong> — it duplicates the table.</li><li><strong>New <code>Scheme</code> variants</strong> — <code>arr</code> ops are enough.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>One graph, two handler behaviours (with/without clauses).</li><li>Governance lives in handler config, not workspace policy.</li><li>Static analysis works on the unnormalised graph.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>handl-runtime/</code> — <code>module_ref</code>/<code>project</code> ops and the loader.</li><li>Handler config for allowlist/depth/resolvers.</li><li>Cycle-detection and contract-inference tests.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The five sections in full, handler clauses, governance and static passes: +<a href="./../design/0009-strategy-c-runtime-module-loading.html"><code>design/0009-strategy-c-runtime-module-loading.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};